<script>
  import { onMount } from "svelte";
  import { currentLang, t } from "../lib/i18n";
  import { gsap } from "gsap";
  import { ScrollTrigger } from "gsap/ScrollTrigger";
  gsap.registerPlugin(ScrollTrigger);

  let animationPlayed = false;
  let heroSection;
  let nextSection;

  function scrollToNextSection() {
    const nextSection = document.querySelector(".services-section") || document.querySelector("#services");
    if (nextSection) {
      nextSection.scrollIntoView({ behavior: "smooth" });
    } else {
      window.scrollTo({
        top: window.innerHeight,
        behavior: "smooth",
      });
    }
  }

  onMount(() => {

    if (!animationPlayed) {
      const tl = gsap.timeline();

      tl.from(".hero-content h1", {
        y: 50,
        opacity: 0,
        duration: 0.8,
        delay: 0.2,
      })
        .from(
          ".hero-content p",
          {
            y: 30,
            opacity: 0,
            duration: 0.6,
          },
          "-=0.3",
        )
        .from(
          ".hero-content .btn",
          {
            y: 20,
            opacity: 0,
            duration: 0.5,
          },
          "-=0.2",
        )
        .from(
          ".hero-overlay",
          {
            opacity: 0.3,
            duration: 0.8,
          },
          "-=0.5",
        );

      animationPlayed = true;
    }

    // Set up parallax effect
    ScrollTrigger.create({
      trigger: ".hero",
      start: "top top",
      end: "bottom top",
      scrub: true,
      onUpdate: (self) => {
        gsap.to(".hero-background", {
          y: self.progress * 200,
          ease: "none",
        });
      },
    });
  });
</script>

<section class="hero" bind:this={heroSection}>
  <div class="hero-background"></div>
  <div class="hero-overlay"></div>
  <div class="container hero-container">
    <div class="hero-content">
      <h1>{t("hero.welcome", $currentLang)}</h1>
      <p>{t("hero.subtitle", $currentLang)}</p>
      <button class="btn btn-primary">{t("hero.cta", $currentLang)}</button>
    </div>

    <div
      class="scroll-down-indicator"
      on:click={scrollToNextSection}
      on:keydown={(e) => e.key === "Enter" && scrollToNextSection()}
      tabindex="0"
      role="button"
      aria-label={$currentLang === "hu" ? "Görgessen lefelé" : "Scroll down"}
    >
      <div class="mouse">
        <div class="wheel"></div>
      </div>
      <div class="scroll-arrows">
        <span></span>
        <span></span>
        <span></span>
      </div>
    </div>
  </div>
</section>

